{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
if (dbPath !== ':memory:') mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
// Upgrade databases created by earlier checkpoints without losing project data.
if (!db.prepare("PRAGMA table_info(projects)").all().some((column) => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

const json = (res, status, value) => {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
};

async function handle(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/?$/);
  const completionRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/?$/);
  async function readBody() {
    let body = '';
    for await (const chunk of req) {
      body += chunk;
      if (body.length > 100_000) throw Object.assign(new Error('Request body too large'), { status: 413 });
    }
    try { return JSON.parse(body); }
    catch { throw Object.assign(new Error('Invalid request body'), { status: 400 }); }
  }
  if (taskRoute && req.method === 'GET') {
    const projectId = Number(taskRoute[1]);
    if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    const tasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id ASC').all(projectId)
      .map((task) => ({ ...task, id: Number(task.id), projectId: Number(task.projectId), completed: Boolean(task.completed) }));
    return json(res, 200, tasks);
  }
  if (taskRoute && req.method === 'POST') {
    const projectId = Number(taskRoute[1]);
    const project = db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 400, { error: 'Archived project' });
    let body;
    try { body = await readBody(); } catch (error) { return json(res, error.status || 400, { error: error.message }); }
    const title = String(body.title ?? '').trim();
    if (!title) return json(res, 400, { error: 'Task title is required' });
    const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
    return json(res, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
  }
  if (completionRoute && req.method === 'PATCH') {
    const projectId = Number(completionRoute[1]);
    const taskId = Number(completionRoute[2]);
    let body;
    try { body = await readBody(); } catch (error) { return json(res, error.status || 400, { error: error.message }); }
    if (typeof body.completed !== 'boolean') return json(res, 400, { error: 'Completion state is required' });
    const project = db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 400, { error: 'Archived project' });
    const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
    if (!result.changes) return json(res, 404, { error: 'Task not found' });
    return json(res, 200, { id: taskId, projectId, completed: body.completed });
  }
  if (url.pathname === '/health' && req.method === 'GET') return json(res, 200, { status: 'ok' });
  const projectStateRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)\/?$/);
  const renameRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/?$/);
  if (renameRoute && req.method === 'PATCH') {
    const id = Number(renameRoute[1]);
    let body;
    try { body = await readBody(); } catch (error) { return json(res, error.status || 400, { error: error.message }); }
    const name = String(body.name ?? '').trim();
    if (!name) return json(res, 400, { error: 'Project name is required' });
    const project = db.prepare('SELECT archived FROM projects WHERE id = ?').get(id);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 400, { error: 'Archived project' });
    db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, id);
    return json(res, 200, { id, name });
  }
  if (projectStateRoute && req.method === 'POST') {
    const id = Number(projectStateRoute[1]);
    const archived = projectStateRoute[2] === 'archive' ? 1 : 0;
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archived, id);
    if (!result.changes) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, { id, archived: Boolean(archived) });
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, db.prepare(`SELECT p.id, p.name, p.archived,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
      FROM projects p ORDER BY p.id ASC`).all().map((p) => ({
        ...p, id: Number(p.id), archived: Boolean(p.archived),
        completedCount: Number(p.completedCount), totalCount: Number(p.totalCount),
      })));
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let name;
    try { name = String((await readBody()).name ?? '').trim(); }
    catch (error) { return json(res, error.status || 400, { error: error.message }); }
    if (!name) return json(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return json(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname))) {
    const html = await readFile(join(root, 'index.html'));
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' });
    return res.end(html);
  }
  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Not found');
}

const server = createServer((req, res) => {
  handle(req, res).catch((error) => {
    console.error(error);
    if (!res.headersSent) json(res, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
    else res.destroy();
  });
});
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on 0.0.0.0:${port}`));

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #182230; background: #f5f7fa; }
    body { margin: 0; }
    main { max-width: 760px; margin: 56px auto; padding: 0 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .task-row { display: flex; align-items: center; gap: 12px; }
    form { margin-bottom: 20px; }
    label { font-weight: 600; }
    input { box-sizing: border-box; min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #aab4c0; border-radius: 6px; font: inherit; }
    button { padding: 10px 14px; border: 0; border-radius: 6px; background: #2457c5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #1b439d; }
    button:focus-visible, input:focus-visible { outline: 3px solid #88aaff; outline-offset: 2px; }
    [role="alert"] { color: #a32121; margin: 12px 0; }
    .project-list { display: grid; gap: 10px; }
    .project-row { justify-content: space-between; padding: 14px 16px; border: 1px solid #d8dee7; border-radius: 8px; background: white; }
    .project-name { overflow-wrap: anywhere; }
    .task-controls { display: flex; align-items: center; gap: 12px; margin: 22px 0; }
    .task-controls label { white-space: nowrap; }
    .task-controls select { padding: 10px 12px; border: 1px solid #aab4c0; border-radius: 6px; font: inherit; }
    .task-list { display: grid; gap: 10px; }
    .task-row { padding: 14px 16px; border: 1px solid #d8dee7; border-radius: 8px; background: white; }
    .task-row input { flex: none; width: 18px; height: 18px; }
    .task-row span { overflow-wrap: anywhere; }
    @media (max-width: 520px) { main { margin-top: 32px; } form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapePath = (id) => `/projects/${encodeURIComponent(id)}`;

    async function loadProjects() {
      const response = await fetch('/api/projects');
      if (!response.ok) throw new Error('Could not load projects');
      return response.json();
    }

    function renderList(projects) {
      app.replaceChildren();
      const heading = document.createElement('h1');
      heading.textContent = 'Workboard';
      app.append(heading);

      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'project-filter';
      filterLabel.textContent = 'Project filter';
      const filter = document.createElement('select');
      filter.id = 'project-filter';
      for (const value of ['Active', 'Archived']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        filter.append(option);
      }

      const form = document.createElement('form');
      const label = document.createElement('label');
      label.htmlFor = 'project-name';
      label.textContent = 'Project name';
      const input = document.createElement('input');
      input.id = 'project-name';
      input.name = 'name';
      input.type = 'text';
      input.autocomplete = 'off';
      const submit = document.createElement('button');
      submit.type = 'submit';
      submit.textContent = 'Create project';
      form.append(label, input, submit);
      const alert = document.createElement('p');
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      const list = document.createElement('section');
      list.className = 'project-list';
      list.setAttribute('aria-label', 'Projects');
      function drawProjects() {
        list.replaceChildren();
        for (const project of projects.filter((item) => item.archived === (filter.value === 'Archived'))) {
          const row = document.createElement('div');
          row.className = 'project-row';
          row.dataset.testid = 'project-row';
          const name = document.createElement('span');
          name.className = 'project-name';
          name.textContent = project.name;
          const summary = document.createElement('span');
          summary.dataset.testid = 'project-summary';
          summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
          const open = document.createElement('button');
          open.type = 'button';
          open.textContent = 'Open project';
          open.addEventListener('click', () => { location.href = escapePath(project.id); });
          const stateButton = document.createElement('button');
          stateButton.type = 'button';
          stateButton.textContent = project.archived ? 'Restore project' : 'Archive project';
          stateButton.addEventListener('click', async () => {
            const action = project.archived ? 'restore' : 'archive';
            const response = await fetch(`/api/projects/${project.id}/${action}`, { method: 'POST' });
            if (response.ok) {
              project.archived = !project.archived;
              drawProjects();
            }
          });
          row.append(name, summary, open, stateButton);
          list.append(row);
        }
      }
      filter.addEventListener('change', drawProjects);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const nameValue = input.value.trim();
        if (!nameValue) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        alert.hidden = true;
        const response = await fetch('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: nameValue }),
        });
        if (!response.ok) {
          alert.textContent = (await response.json()).error || 'Could not create project';
          alert.hidden = false;
          return;
        }
        renderList([...projects, { ...await response.json(), archived: false, completedCount: 0, totalCount: 0 }]);
      });
      app.append(filterLabel, filter, form, alert, list);
      drawProjects();
    }

    async function renderProject(id) {
      const projects = await loadProjects();
      const project = projects.find((item) => String(item.id) === id);
      if (!project) {
        app.replaceChildren();
        const heading = document.createElement('h1');
        heading.textContent = 'Project not found';
        app.append(heading);
        return;
      }
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
      if (!response.ok) throw new Error('Could not load tasks');
      const tasks = await response.json();
      app.replaceChildren();
      const back = document.createElement('button');
      back.type = 'button';
      back.textContent = 'Projects';
      back.addEventListener('click', () => { location.href = '/'; });
      const heading = document.createElement('h1');
      heading.textContent = project.name;
      const renameForm = document.createElement('form');
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = 'new-project-name';
      renameLabel.textContent = 'New project name';
      const renameInput = document.createElement('input');
      renameInput.id = 'new-project-name';
      renameInput.type = 'text';
      renameInput.autocomplete = 'off';
      renameInput.disabled = project.archived;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename project';
      renameButton.disabled = project.archived;
      renameForm.append(renameLabel, renameInput, renameButton);
      const archivedNotice = document.createElement('p');
      archivedNotice.textContent = 'Archived project';
      archivedNotice.hidden = !project.archived;
      const form = document.createElement('form');
      const label = document.createElement('label');
      label.htmlFor = 'task-title';
      label.textContent = 'Task title';
      const input = document.createElement('input');
      input.id = 'task-title';
      input.name = 'title';
      input.type = 'text';
      input.autocomplete = 'off';
      const submit = document.createElement('button');
      submit.type = 'submit';
      submit.textContent = 'Create task';
      submit.disabled = project.archived;
      input.disabled = project.archived;
      form.append(label, input, submit);
      const alert = document.createElement('p');
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      const controls = document.createElement('div');
      controls.className = 'task-controls';
      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'task-filter';
      filterLabel.textContent = 'Task filter';
      const filter = document.createElement('select');
      filter.id = 'task-filter';
      for (const value of ['All', 'Open', 'Completed']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        filter.append(option);
      }
      controls.append(filterLabel, filter);
      const list = document.createElement('section');
      list.className = 'task-list';
      list.setAttribute('aria-label', 'Tasks');
      function drawTasks() {
        list.replaceChildren();
        const matching = tasks.filter((task) => filter.value === 'All' || (filter.value === 'Completed') === task.completed);
        for (const task of matching) {
          const row = document.createElement('div');
          row.className = 'task-row';
          row.dataset.testid = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          const title = document.createElement('span');
          title.textContent = task.title;
          checkbox.addEventListener('change', async () => {
            checkbox.disabled = true;
            const saved = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            if (saved.ok) task.completed = checkbox.checked;
            checkbox.disabled = false;
            drawTasks();
          });
          row.append(checkbox, title);
          list.append(row);
        }
      }
      filter.addEventListener('change', drawTasks);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        alert.hidden = true;
        const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
        });
        if (!created.ok) {
          alert.textContent = (await created.json()).error || 'Could not create task';
          alert.hidden = false;
          return;
        }
        tasks.push(await created.json());
        input.value = '';
        drawTasks();
      });
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          renameInput.focus();
          return;
        }
        const saved = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!saved.ok) {
          alert.textContent = (await saved.json()).error || 'Could not rename project';
          alert.hidden = false;
          return;
        }
        project.name = (await saved.json()).name;
        heading.textContent = project.name;
        renameInput.value = '';
        alert.hidden = true;
      });
      app.append(back, heading, archivedNotice, renameForm, form, alert, controls, list);
      drawTasks();
    }

    const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
    (match ? renderProject(match[1]) : loadProjects().then(renderList)).catch(() => {
      app.textContent = 'Unable to load Workboard. Please refresh the page.';
    });
  </script>
</body>
</html>

